import 'package:flutter/material.dart';import 'package:mobile_scanner/mobile_scanner.dart';import 'camera_live_page.dart';
class CameraJoinPage extends StatefulWidget{const CameraJoinPage({super.key});@override State<CameraJoinPage> createState()=>_S();}class _S extends State<CameraJoinPage>{bool handled=false;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Scan Pairing QR')),body:MobileScanner(onDetect:(capture){if(handled||capture.barcodes.isEmpty)return;final raw=capture.barcodes.first.rawValue;if(raw==null)return;final uri=Uri.tryParse(raw);final token=uri?.queryParameters['token'];if(token!=null){handled=true;Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>CameraLivePage(token:token)));}}));}
